#!/usr/bin/env python2
import json
import socket
from BaseHTTPServer import BaseHTTPRequestHandler, HTTPServer

INVENTORY = [
    {"id": 1, "name": "Widget A", "qty": 120},
    {"id": 2, "name": "Widget B", "qty": 75},
    {"id": 3, "name": "Widget C", "qty": 300},
]

HOSTNAME = socket.gethostname()

class InventoryHandler(BaseHTTPRequestHandler):
    def _send(self, code, payload):
        body = json.dumps(payload)
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/health":
            self._send(200, {"status": "ok", "backend": HOSTNAME})
        elif self.path == "/" or self.path == "/inventory":
            self._send(200, {"backend": HOSTNAME, "inventory": INVENTORY})
        else:
            self._send(404, {"error": "not found"})

    def log_message(self, fmt, *args):
        pass

if __name__ == "__main__":
    server = HTTPServer(("0.0.0.0", 8080), InventoryHandler)
    server.serve_forever()
PYEOF
